import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

@Controller('api/v1')
export class FnSfr03804Controller {
  @Get('/menu-usage-statistics')
  async listMenuUsageStatistics(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const query = checks.queryOf(req.query);
    const startRaw = query['startDate'];
    const endRaw = query['endDate'];
    const startDate = startRaw === undefined || startRaw === null || startRaw === '' ? null : String(startRaw);
    const endDate = endRaw === undefined || endRaw === null || endRaw === '' ? null : String(endRaw);
    if (startDate !== null && !DATE_PATTERN.test(startDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일 형식이 올바르지 않습니다.');
    }
    if (endDate !== null && !DATE_PATTERN.test(endDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 종료일 형식이 올바르지 않습니다.');
    }
    const pageRaw = query['page'];
    const sizeRaw = query['size'];
    const page = pageRaw === undefined || pageRaw === null || pageRaw === '' ? 0 : Number(pageRaw);
    const size = sizeRaw === undefined || sizeRaw === null || sizeRaw === '' ? DEFAULT_SIZE : Number(sizeRaw);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
    }
    if (!Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
    }
    const limit = Math.min(size, MAX_SIZE);
    return transaction(async (db) => {
      if (startDate !== null && endDate !== null) {
        const check = await db.query(
          'SELECT CAST(:startDate AS date) > CAST(:endDate AS date) AS "invalid"',
          { startDate, endDate },
        );
        if (check[0] && check[0]['invalid'] === true) {
          throw new ApiError(422, 'INVALID_PERIOD', '시작일이 종료일보다 늦을 수 없습니다.');
        }
      }
      // 기간을 지정하지 않으면 전체 기간 (결정)
      const where =
        "a.event_type = '메뉴사용'" +
        ' AND (CAST(:startDate AS date) IS NULL OR a.accessed_at >= CAST(:startDate AS date))' +
        ' AND (CAST(:endDate AS date) IS NULL OR a.accessed_at < CAST(:endDate AS date) + 1)';
      const totalRows = await db.query(
        'SELECT COUNT(DISTINCT a.menu_id) AS "total" FROM access_log a WHERE ' + where,
        { startDate, endDate },
      );
      const total = Number(totalRows[0] ? totalRows[0]['total'] : 0);
      const rows = await db.query(
        'SELECT m.menu_id AS "menuId", m.name AS "menuName", COUNT(*) AS "usageCount"' +
          ' FROM access_log a JOIN menu m ON m.menu_id = a.menu_id' +
          ' WHERE ' + where +
          ' GROUP BY m.menu_id, m.name' +
          ' ORDER BY COUNT(*) DESC, m.menu_id' +
          ' LIMIT :limit OFFSET :offset',
        { startDate, endDate, limit, offset: page * limit },
      );
      const items = rows.map((r: Record<string, unknown>) => ({
        menuId: Number(r['menuId']),
        menuName: r['menuName'],
        usageCount: Number(r['usageCount']),
      }));
      return { items, page, size: limit, total };
    });
  }
}

