import { useState } from 'react';
import { call, useData, Filters, Field, DateInput, DataTable, Pager, Num, Tiles, ErrorText } from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;

export default function FnSfr03804Page({ role, notify }: PageProps) {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [applied, setApplied] = useState({ startDate: '', endDate: '' });
  const [page, setPage] = useState(0);
  const [formError, setFormError] = useState('');

  const { data, error, loading } = useData<Page>(
    () => call<Page>('GET', '/menu-usage-statistics', role, undefined, { ...applied, page, size: SIZE }),
    [applied.startDate, applied.endDate, page, role],
  );

  const rows: Row[] = data ? data.items : [];
  const total = data ? data.total : 0;
  const maxCount = rows.reduce((max, r) => Math.max(max, Number(r['usageCount']) || 0), 0);
  const pageSum = rows.reduce((sum, r) => sum + (Number(r['usageCount']) || 0), 0);
  const top = rows.length > 0 ? String(rows[0]['menuName']) : '-';

  function search() {
    if (startDate && endDate && startDate > endDate) {
      setFormError('시작일이 종료일보다 늦을 수 없습니다.');
      notify('조회 기간을 확인해 주세요.');
      return;
    }
    setFormError('');
    setPage(0);
    setApplied({ startDate, endDate });
  }

  function reset() {
    setFormError('');
    setStartDate('');
    setEndDate('');
    setPage(0);
    setApplied({ startDate: '', endDate: '' });
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>집계 메뉴</h2>
        <Tiles items={[['메뉴 수', <Num value={total} />]]} />
      </section>
      <section className="box span-4">
        <h2>현재 쪽 사용</h2>
        <Tiles items={[['사용 건수', <Num value={pageSum} />]]} />
      </section>
      <section className="box span-4">
        <h2>최다 사용 메뉴</h2>
        <Tiles items={[['메뉴명', top]]} />
      </section>
      <section className="box span-12">
        <h2>메뉴별 사용 통계</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일" hint="비우면 전체 기간">
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일">
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
        </Filters>
        {formError ? <ErrorText text={formError} /> : null}
        {error ? <ErrorText text={error} /> : null}
        {loading ? <p>불러오는 중입니다.</p> : null}
        {!loading && !error && rows.length === 0 ? <p>통계 없음: 집계할 메뉴 사용 내역이 없습니다.</p> : null}
        <div className="chart">
          {rows.map((r) => {
            const count = Number(r['usageCount']) || 0;
            const width = maxCount > 0 ? Math.round((count / maxCount) * 100) : 0;
            return (
              <div className="chart-row" key={String(r['menuId'])}>
                <span className="chart-label">{String(r['menuName'])}</span>
                <div className="chart-track">
                  <div className="chart-bar" style={{ width: width + '%' }} />
                </div>
                <Num value={count} />
              </div>
            );
          })}
        </div>
        <DataTable
          columns={[
            { key: 'menuName', label: '메뉴명' },
            { key: 'usageCount', label: '메뉴별 사용 건수', render: (r: Row) => <Num value={r['usageCount']} /> },
          ]}
          rows={rows}
          empty="통계 없음"
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
    </div>
  );
}
